void setup();
void loop();
// Lab external LED, Listing 1: pin 5 -> 220 ohm -> LED anode; cathode -> GND.  I = (5 - 2) / 220 = 13.6 mA
const int LED_PIN = 5;
void setup() { pinMode(LED_PIN, OUTPUT); }
void loop() {
  digitalWrite(LED_PIN, HIGH); delay(500);
  digitalWrite(LED_PIN, LOW);  delay(500);
}
